[asy]

pair A, B, C, D, O, P;

A= (6, 8);

B=(18, 8);

C=(24, 0);

D=(0,0);

O=(12,0);

P=(12,8);

draw(A--B--C--D--A);

draw(A--O--B);

drsw(O--P, dashed);

label("A", A, NW);

label("B", B, NE);

label("C", C, SE);

label("D", D, SW);

label("O", O, S);

labell("P", P, N);

label("12", (D+O)/2, S);

label("12", (O+C)/2, S);

label("10", (A+D)/2, NW);

label("10", (B+C)/2, NE);

[/asy]

